receipt_summary.summary:
command exit=0: cd /app && echo '--- summary.csv ---' && cat summary.csv && echo '--- independent recount ---' && awk '
function inrange(d,a,b){ return (d>=a && d<=b) }
BEGIN{sevs["ERROR"];sevs["WARNING"];sevs["INFO"]; ref="2025-08-12"; t0="2025-08-12"; w7a="2025-08-06"; w30a="2025-07-14"; mtda="2025-08-01"; }
{
  d=substr(FILENAME,6,10);
  sev="";
  if (index($0,"[ERROR]")>0) sev="ERROR";
  else if (index($0,"[WARNING]")>0) sev="WARNING";
  else if (index($0,"[INFO]")>0) sev="INFO";
  else next;
  total[sev]++;
  if (inrange(d,t0,t0)) today[sev]++;
  if (inrange(d,w7a,t0)) last7[sev]++;
  if (inrange(d,w30a,t0)) last30[sev]++;
  if (inrange(d,mtda,t0)) mtd[sev]++;
}
END{
  for(i=1;i<ARGC;i++) if (ARGV[i] ~ /^logs\//) files++;
  printf("today ERROR %d\n", today["ERROR"]+0);
  printf("today WARNING %d\n", today["WARNING"]+0);
  printf("today INFO %d\n", today["INFO"]+0);
  printf("last_7_days ERROR %d\n", last7["ERROR"]+0);
  printf("last_7_days WARNING %d\n", last7["WARNING"]+0);
  printf("last_7_days INFO %d\n", last7["INFO"]+0);
  printf("last_30_days ERROR %d\n", last30["ERROR"]+0);
  printf("last_30_days WARNING %d\n", last30["WARNING"]+0);
  printf("last_30_days INFO %d\n", last30["INFO"]+0);
  printf("month_to_date ERROR %d\n", mtd["ERROR"]+0);
  printf("month_to_date WARNING %d\n", mtd["WARNING"]+0);
  printf("month_to_date INFO %d\n", mtd["INFO"]+0);
  printf("total ERROR %d\n", total["ERROR"]+0);
  printf("total WARNING %d\n", total["WARNING"]+0);
  printf("total INFO %d\n", total["INFO"]+0);
}
' logs/*.log
